TLM.f("Tempora/Quad6-6r",{"officium":"Sabbato Sancto","rule":["Full text","Prefatio=Pasch;"],"ruleInherited":["no Gloria","Credo","Prefatio=Quad5","Prelude","Passio","omit commemoratio incipit","no Ultima Evangelium"],"fallback":"Tempora/Quad6-0r","from":{"Introitus":"Tempora/Quad6-0r","Oratio":"Tempora/Quad6-0r","Lectio":"Tempora/Quad6-0r","Graduale":"Tempora/Quad6-0r","Evangelium":"Tempora/Quad6-0r","Offertorium":"Tempora/Quad6-0r","Secreta":"Tempora/Quad6-0r","Communio":"Tempora/Quad6-0r","Postcommunio":"Tempora/Quad6-0r","Munda Cor Passionis":"Tempora/Quad6-0r"},"sections":{"Introitus":[{"k":"ref","la":"Ps 21:20 et 22"},{"k":"text","la":"Dómine, ne longe fácias auxílium tuum a me, ad defensiónem meam áspice: líbera me de ore leónis, et a córnibus unicórnium humilitátem meam."},{"k":"ref","la":"Ps 21:2"},{"k":"text","la":"Deus, Deus meus, réspice in me: quare me dereliquísti? longe a salúte mea verba delictórum meórum."},{"k":"text","la":"Dómine, ne longe fácias auxílium tuum a me, ad defensiónem meam áspice: líbera me de ore leónis, et a córnibus unicórnium humilitátem meam."}],"Oratio":[{"k":"text","la":"Omnípotens sempitérne Deus, qui humáno géneri, ad imitándum humilitátis exémplum, Salvatórem nostrum carnem súmere et crucem subíre fecísti: concéde propítius; ut et patiéntiæ ipsíus habére documénta et resurrectiónis consórtia mereámur."},{"k":"macro","name":"Per eumdem"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Philippénses"},{"k":"ref","la":"Phil 2:5-11"},{"k":"text","la":"Fratres: Hoc enim sentíte in vobis, quod et in Christo Jesu: qui, cum in forma Dei esset, non rapínam arbitrátus est esse se æquálem Deo: sed semetípsum exinanívit, formam servi accípiens, in similitúdinem hóminum factus, et hábitu invéntus ut homo. Humiliávit semetípsum, factus obédiens usque ad mortem, mortem autem crucis. Propter quod et Deus exaltávit illum: et donávit illi nomen, quod est super omne nomen: (hic genuflectitur) ut in nómine Jesu omne genu flectátur cœléstium, terréstrium et infernórum: et omnis lingua confiteátur, quia Dóminus Jesus Christus in glória est Dei Patris."}],"Graduale":[{"k":"ref","la":"Ps 72:24 et 1-3"},{"k":"text","la":"Tenuísti manum déxteram meam: et in voluntáte tua deduxísti me: et cum glória assumpsísti me."},{"k":"text","la":"Quam bonus Israël Deus rectis corde! mei autem pæne moti sunt pedes: pæne effúsi sunt gressus mei: quia zelávi in peccatóribus, pacem peccatórum videns.","mark":"V"},{"k":"sep"},{"k":"ref","la":"Tractus 21:2-9, 18, 19, 22, 24, 32"},{"k":"text","la":"Deus, Deus meus, réspice in me: quare me dereliquísti?"},{"k":"text","la":"Longe a salúte mea verba delictórum meórum.","mark":"V"},{"k":"text","la":"Deus meus, clamábo per diem, nec exáudies: in nocte, et non ad insipiéntiam mihi.","mark":"V"},{"k":"text","la":"Tu autem in sancto hábitas, laus Israël.","mark":"V"},{"k":"text","la":"In te speravérunt patres nostri: speravérunt, et liberásti eos.","mark":"V"},{"k":"text","la":"Ad te clamavérunt, et salvi facti sunt: in te speravérunt, et non sunt confúsi.","mark":"V"},{"k":"text","la":"Ego autem sum vermis, et non homo: oppróbrium hóminum et abjéctio plebis.","mark":"V"},{"k":"text","la":"Omnes, qui vidébant me, aspernabántur me: locúti sunt lábiis et movérunt caput.","mark":"V"},{"k":"text","la":"Sperávit in Dómino, erípiat eum: salvum fáciat eum, quóniam vult eum.","mark":"V"},{"k":"text","la":"Ipsi vero consideravérunt et conspexérunt me: divisérunt sibi vestiménta mea, et super vestem meam misérunt sortem.","mark":"V"},{"k":"text","la":"Líbera me de ore leónis: et a córnibus unicórnium humilitátem meam.","mark":"V"},{"k":"text","la":"Qui timétis Dóminum, laudáte eum: univérsum semen Jacob, magnificáte eum.","mark":"V"},{"k":"text","la":"Annuntiábitur Dómino generátio ventúra: et annuntiábunt cœli justítiam ejus.","mark":"V"},{"k":"text","la":"Pópulo, qui nascétur, quem fecit Dóminus.","mark":"V"}],"Evangelium":[{"k":"text","la":"v. Pássio Dómini nostri Jesu Christi secúndum Matthǽum"},{"k":"ref","la":"Matt 26:36-75; 27:1-60"},{"k":"text","la":"Tunc venit Jesus cum illis in villam, quæ dícitur Gethsémani, et dixit discípulis suis: J. Sedéte hic, donec vadam illuc et orem. C. Et assúmpto Petro et duóbus fíliis Zebedæi, cœpit contristári et mæstus esse. Tunc ait illis: J. Tristis est ánima mea usque ad mortem: sustinéte hic, et vigilate mecum. C. Et progréssus pusíllum, prócidit in fáciem suam, orans et dicens: J. Pater mi, si possíbile est, tránseat a me calix iste: Verúmtamen non sicut ego volo, sed sicut tu. C. Et venit ad discípulos suos, et invénit eos dormiéntes: et dicit Petro: J. Sic non potuístis una hora vigiláre mecum? Vigiláte et oráte, ut non intrétis in tentatiónem. Spíritus quidem promptus est, caro autem infírma. C. Iterum secúndo ábiit et orávit, dicens: J. Pater mi, si non potest hic calix transíre, nisi bibam illum, fiat volúntas tua. C. Et venit íterum, et invenit eos dormiéntes: erant enim óculi eórum graváti. Et relíctis illis, íterum ábiit et orávit tértio, eúndem sermónem dicens. Tunc venit ad discípulos suos, et dicit illis: J. Dormíte jam et requiéscite: ecce, appropinquávit hora, et Fílius hóminis tradétur in manus peccatórum. Súrgite, eámus: ecce, appropinquávit, qui me tradet. C. Adhuc eo loquénte, ecce, Judas, unus de duódecim, venit, et cum eo turba multa cum gládiis et fústibus, missi a princípibus sacerdótum et senióribus pópuli. Qui autem trádidit eum, dedit illis signum, dicens: S. Quemcúmque osculátus fúero, ipse est, tenéte eum. C. Et conféstim accédens ad Jesum, dixit: S. Ave, Rabbi. C. Et osculátus est eum. Dixítque illi Jesus: J. Amíce, ad quid venísti? C. Tunc accessérunt, et manus injecérunt in Jesum et tenuérunt eum. Et ecce, unus ex his, qui erant cum Jesu, exténdens manum, exémit gládium suum, et percútiens servum príncipis sacerdótum, amputávit aurículam ejus. Tunc ait illi Jesus: J. Convérte gládium tuum in locum suum. Omnes enim, qui accéperint gládium, gládio períbunt. An putas, quia non possum rogáre Patrem meum, et exhibébit mihi modo plus quam duódecim legiónes Angelórum? Quómodo ergo implebúntur Scripturæ, quia sic oportet fíeri? C. In illa hora dixit Jesus turbis: J. Tamquam ad latrónem exístis cum gládiis et fústibus comprehéndere me: cotídie apud vos sedébam docens in templo, et non me tenuístis. C. Hoc autem totum factum est, ut adimpleréntur Scripturæ Prophetárum. Tunc discípuli omnes, relícto eo, fugérunt. At illi tenéntes Jesum, duxérunt ad Cáipham, príncipem sacerdótum, ubi scribæ et senióres convénerant. Petrus autem sequebátur eum a longe, usque in átrium príncipis sacerdótum. Et ingréssus intro, sedébat cum minístris, ut vidéret finem. Príncipes autem sacerdótum et omne concílium quærébant falsum testimónium contra Jesum, ut eum morti tráderent: et non invenérunt, cum multi falsi testes accessíssent. Novíssime autem venérunt duo falsi testes et dixérunt: S. Hic dixit: Possum destrúere templum Dei, et post tríduum reædificáre illud. C. Et surgens princeps sacerdótum, ait illi: S. Nihil respóndes ad ea, quæ isti advérsum te testificántur? C. Jesus autem tacébat. Et princeps sacerdótum ait illi: S. Adjúro te per Deum vivum, ut dicas nobis, si tu es Christus, Fílius Dei. C. Dicit illi Jesus: J. Tu dixísti. Verúmtamen dico vobis, ámodo vidébitis Fílium hóminis sedéntem a dextris virtútis Dei, et veniéntem in núbibus cœli. C. Tunc princeps sacerdótum scidit vestiménta sua, dicens: S. Blasphemávit: quid adhuc egémus téstibus? Ecce, nunc audístis blasphémiam: quid vobis vidétur? C. At illi respondéntes dixérunt: S. Reus est mortis. C. Tunc exspuérunt in fáciem ejus, et cólaphis eum cecidérunt, álii autem palmas in fáciem ejus dedérunt, dicéntes: S. Prophetíza nobis, Christe, quis est, qui te percússit? C. Petrus vero sedébat foris in átrio: et accéssit ad eum una ancílla, dicens: S. Et tu cum Jesu Galilæo eras. C. At ille negávit coram ómnibus, dicens: S. Néscio, quid dicis. C. Exeúnte autem illo jánuam, vidit eum ália ancílla, et ait his, qui erant ibi: S. Et hic erat cum Jesu Nazaréno. C. Et íterum negávit cum juraménto: Quia non novi hóminem. Et post pusíllum accessérunt, qui stabant, et dixérunt Petro: S. Vere et tu ex illis es: nam et loquéla tua maniféstum te facit. C. Tunc cœpit detestári et juráre, quia non novísset hóminem. Et contínuo gallus cantávit. Et recordátus est Petrus verbi Jesu, quod díxerat: Priúsquam gallus cantet, ter me negábis. Et egréssus foras, flevit amáre. Mane autem facto, consílium iniérunt omnes príncipes sacerdótum et senióres pópuli advérsus Jesum, ut eum morti tráderent. Et vinctum adduxérunt eum, et tradidérunt Póntio Piláto præsidi. Tunc videns Judas, qui eum trádidit, quod damnátus esset, pæniténtia ductus, réttulit trigínta argénteos princípibus sacerdótum et senióribus, dicens: S. Peccávi, tradens sánguinem justum. C. At illi dixérunt: S. Quid ad nos? Tu vidéris. C. Et projéctis argénteis in templo, recéssit: et ábiens, láqueo se suspéndit. Príncipes autem sacerdótum, accéptis argénteis, dixérunt: S. Non licet eos míttere in córbonam: quia prétium sánguinis est. C. Consílio autem ínito, emérunt ex illis agrum fíguli, in sepultúram peregrinórum. Propter hoc vocátus est ager ille, Hacéldama, hoc est, ager sánguinis, usque in hodiérnum diem. Tunc implétum est, quod dictum est per Jeremíam Prophétam, dicéntem: Et accepérunt trigínta argénteos prétium appretiáti, quem appretiavérunt a fíliis Israël: et dedérunt eos in agrum fíguli, sicut constítuit mihi Dóminus. Jesus autem stetit ante præsidem, et interrogávit eum præses, dicens: S. Tu es Rex Judæórum? C. Dicit illi Jesus: J. Tu dicis. C. Et cum accusarétur a princípibus sacerdótum et senióribus, nihil respóndit. Tunc dicit illi Pilátus: S. Non audis, quanta advérsum te dicunt testimónia? C. Et non respóndit ei ad ullum verbum, ita ut mirarétur præses veheménter. Per diem autem sollémnem consuéverat præses pópulo dimíttere unum vinctum, quem voluíssent. Habébat autem tunc vinctum insígnem, qui dicebátur Barábbas. Congregátis ergo illis, dixit Pilátus: S. Quem vultis dimíttam vobis: Barábbam, an Jesum, qui dícitur Christus? C. Sciébat enim, quod per invídiam tradidíssent eum. Sedénte autem illo pro tribunáli, misit ad eum uxor ejus, dicens: S. Nihil tibi et justo illi: multa enim passa sum hódie per visum propter eum. C. Príncipes autem sacerdótum et senióres persuasérunt populis, ut péterent Barábbam, Jesum vero pérderent. Respóndens autem præses, ait illis: S. Quem vultis vobis de duóbus dimítti? C. At illi dixérunt: S. Barábbam. C. Dicit illis Pilátus: S. Quid ígitur fáciam de Jesu, qui dícitur Christus? C. Dicunt omnes: S. Crucifigátur. C. Ait illis præses: S. Quid enim mali fecit? C. At illi magis clamábant, dicéntes: S. Crucifigátur. C. Videns autem Pilátus, quia nihil profíceret, sed magis tumúltus fíeret: accépta aqua, lavit manus coram pópulo, dicens: S. Innocens ego sum a sánguine justi hujus: vos vidéritis. C. Et respóndens univérsus pópulus, dixit: S. Sanguis ejus super nos et super fílios nostros. C. Tunc dimísit illis Barábbam: Jesum autem flagellátum trádidit eis, ut crucifigerétur. Tunc mílites præsidis suscipiéntes Jesum in prætórium, congregavérunt ad eum univérsam cohórtem: et exuéntes eum, chlámydem coccíneam circumdedérunt ei: et plecténtes corónam de spinis, posuérunt super caput ejus, et arúndinem in déxtera ejus. Et genu flexo ante eum, illudébant ei, dicéntes: S. Ave, Rex Judæórum. C. Et exspuéntes in eum, accepérunt arúndinem, et percutiébant caput ejus. Et postquam illusérunt ei, exuérunt eum chlámyde et induérunt eum vestiméntis ejus, et duxérunt eum, ut crucifígerent. Exeúntes autem, invenérunt hóminem Cyrenæum, nómine Simónem: hunc angariavérunt, ut tólleret crucem ejus. Et venérunt in locum, qui dícitur Gólgotha, quod est Calváriæ locus. Et dedérunt ei vinum bíbere cum felle mixtum. Et cum gustásset, nóluit bibere. Postquam autem crucifixérunt eum, divisérunt vestiménta ejus, sortem mitténtes: ut implerétur, quod dictum est per Prophétam dicentem: Divisérunt sibi vestiménta mea, et super vestem meam misérunt sortem. Et sedéntes, servábant eum. Et imposuérunt super caput ejus causam ipsíus scriptam: Hic est Jesus, Rex Judæórum. Tunc crucifíxi sunt cum eo duo latrónes: unus a dextris et unus a sinístris. Prætereúntes autem blasphemábant eum, movéntes cápita sua et dicéntes: S. Vah, qui déstruis templum Dei et in tríduo illud reædíficas: salva temetípsum. Si Fílius Dei es, descénde de cruce. C. Simíliter et príncipes sacerdótum illudéntes cum scribis et senióribus, dicébant: S. Alios salvos fecit, seípsum non potest salvum fácere: si Rex Israël est, descéndat nunc de cruce, et crédimus ei: confídit in Deo: líberet nunc, si vult eum: dixit enim: Quia Fílius Dei sum. C. Idípsum autem et latrónes, qui crucifíxi erant cum eo, improperábant ei. A sexta autem hora ténebræ factæ sunt super univérsam terram usque ad horam nonam. Et circa horam nonam clamávit Jesus voce magna, dicens: J. Eli, Eli, lamma sabactháni? C. Hoc est: J. Deus meus, Deus meus, ut quid dereliquísti me? C. Quidam autem illic stantes et audiéntes dicébant: S. Elíam vocat iste. C. Et contínuo currens unus ex eis, accéptam spóngiam implévit acéto et impósuit arúndini, et dabat ei bíbere. Céteri vero dicébant: S. Sine, videámus, an véniat Elías líberans eum. C. Jesus autem íterum clamans voce magna, emísit spíritum."},{"k":"rubric","la":"Hic genuflectitur, et pausatur aliquantulum."},{"k":"text","la":"Et ecce, velum templi scissum est in duas partes a summo usque deórsum: et terra mota est, et petræ scissæ sunt, et monuménta apérta sunt: et multa córpora sanctórum, qui dormíerant, surrexérunt. Et exeúntes de monuméntis post resurrectiónem ejus, venérunt in sanctam civitátem, et apparuérunt multis. Centúrio autem et qui cum eo erant, custodiéntes Jesum, viso terræmótu et his, quæ fiébant, timuérunt valde, dicéntes: S. Vere Fílius Dei erat iste. C. Erant autem ibi mulíeres multæ a longe, quæ secútæ erant Jesum a Galilæa, ministrántes ei: inter quas erat María Magdaléne, et María Jacóbi, et Joseph mater, et mater filiórum Zebedæi. Cum autem sero factum esset, venit quidam homo dives ab Arimathæa, nómine Joseph, qui et ipse discípulus erat Jesu. Hic accéssit ad Pilátum, et pétiit corpus Jesu. Tunc Pilátus jussit reddi corpus. Et accépto córpore, Joseph invólvit illud in síndone munda. Et pósuit illud in monuménto suo novo, quod excíderat in petra. Et advólvit saxum magnum ad óstium monuménti, et ábiit."}],"Offertorium":[{"k":"ref","la":"Ps 68:21-22"},{"k":"text","la":"Impropérium exspectávit cor meum et misériam: et sustínui, qui simul mecum contristarétur, et non fuit: consolántem me quæsívi, et non invéni: et dedérunt in escam meam fel, et in siti mea potavérunt me acéto."}],"Secreta":[{"k":"text","la":"Concéde, quǽsumus, Dómine: ut óculis tuæ majestátis munus oblátum, et grátiam nobis devotiónis obtíneat, et efféctum beátæ perennitátis acquírat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 26:42"},{"k":"text","la":"Pater, si non potest hic calix transíre, nisi bibam illum: fiat volúntas tua."}],"Postcommunio":[{"k":"text","la":"Per hujus, Dómine, operatiónem mystérii: et vitia nostra purgéntur, et justa desidéria compleántur."},{"k":"macro","name":"Per Dominum"}],"Munda Cor Passionis":[{"k":"text","la":"Munda cor meum ac lábia mea, omnípotens Deus, qui lábia Isaíæ Prophétæ cálculo mundásti igníto: ita me tua grata miseratióne dignáre mundáre, ut sanctum Evangélium tuum digne váleam nuntiáre. Per Christum, Dóminum nostrum. Amen."},{"k":"text","la":"Jube, domne, benedícere.","mark":"D"},{"k":"text","la":"Dóminus sit in córdibus vestris et in lábiis vestris: ut digne et competénter annuntiétis Evangélium suum: In nómine Patris, et Fílii, + et Spíritus Sancti.","mark":"S"},{"k":"text","la":"Amen.","mark":"D"}],"Prelude":[{"k":"head","la":"Benedictio ignis"},{"k":"rubric","la":"Hora competenti tobaleis cooperiuntur ! altaria, sed candelæ exstinctæ manent usque ! ad principium Missæ. Interim excutitur ! ignis de lapide, et ex eo accenduntur carbones."},{"k":"sep"},{"k":"rubric","la":"Celebrans induitur amictu, alba, cingulo, ! stola et pluviali violacei coloris; ministri ! sacri amictu, alba, cingulo, diaconus ! stola et dalmatica, subdiaconus tunicella, ! eiusdem coloris."},{"k":"sep"},{"k":"rubric","la":"(Sacerdos induitur amictu, alba, cingulo, ! stola et pluviali violaceo, vel manet sine ! casula.)"},{"k":"sep"},{"k":"rubric","la":"Adstantibus ministris, seu ministrantibus ! cum cruce, aqua benedicta et incenso, ! sive ante portam, sive in aditu ecclesiæ, vel ! intus eam, ubi scilicet populus ritum sacrum ! melius sequi possit, celebrans benedicit ! novum ignem, dicens:"},{"k":"macro","name":"DominusVobiscum"},{"k":"text","la":"Orémus."},{"k":"text","la":"Deus, qui per Fílium tuum, angulárem scílicet lápidem, claritátis tuæ ignem fidélibus contulísti: prodúctum e sílice, nostris profutúrum úsibus, novum hunc ignem sanctí + fica: et concéde nobis, ita per hæc festa paschália cœléstibus desidériis inflammári; ut ad perpétuæ claritátis, puris méntibus, valeámus festa pertíngere. Per eúndem Christum Dóminum nostrum."},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"rubric","la":"Deinde ignem ter aspergit, nihil dicens."},{"k":"sep"},{"k":"rubric","la":"Acolythus, seu unus ministrantium, ! assumens de carbonibus benedictis, ponit ! in thuribulo; celebrans vero ponit incensum ! in thuribulo, benedicens illud more ! solito, ignemque ter adolet incenso."},{"k":"sep"},{"k":"head","la":"De benedictione cerei Paschalis"},{"k":"rubric","la":"Novo igne benedicto, acolythus, seu ! unus ministrantium, portat cereum paschalem ! in medium, ante celebrantem, qui cum ! stilo, inter extrema foramina ad insertionem ! granorum incensi destinata, incidit ! crucem. Deinde facit super earn litteram ! græcam Alpha, subtus vero litteram Omega, ! et inter bracchia crucis quatuor numeros ! exprimentes annum currentem, interim ! dicens:"},{"k":"text","la":"Christus heri et hódie, (incidit hastam erectam)"},{"k":"text","la":"Princípium et Finis, (incidit hastam transversam)"},{"k":"text","la":"Alpha (incidit supra hastam erectam litteram &Alpha;)"},{"k":"text","la":"et Omega; (incidit subtus hastam erectam litteram &Omega;)"},{"k":"text","la":"Ipsíus sunt témpora (incidit primum numerum anni currentis in angulo sinistro superiore crucis)"},{"k":"text","la":"et sǽcula; (incidit secundum numerum anni currentis in angulo dextro superiore crucis)"},{"k":"text","la":"Ipsi gloria et imperium (incidit tertium numerum anni currentis in angulo sinistro inferiore crucis)"},{"k":"text","la":"per universa æternitátis sǽcula. Amen. (incidit quartum numerum anni currentis in angulo dextro inferiore crucis)"},{"k":"sep"},{"k":"rubric","la":"Incisione crucis et aliorum signorum, ! quæ coloribus vel alio modo antea præparari ! possunt, peracta, diaconus, seu alius ! ministranttiun, præbet celebranti grana incensi, ! quæ idem celebrans, si non sunt benedicta ! ter aspergit et ter adolet incenso, ! nihil dicens. Deinde infigit quinque grana ! in foramina, interim dicens:"},{"k":"text","la":"Per sua sancta vúlnera"},{"k":"text","la":"gloriósa"},{"k":"text","la":"custódiat"},{"k":"text","la":"et consérvet nos"},{"k":"text","la":"Christus Dóminus. Amen."},{"k":"sep"},{"k":"rubric","la":"Tum diaconus, seu unus ministrantium, ! porrigit celebranti parvam candelam, ! de novo igne accensam, qua cereum accendit, ! dicens:"},{"k":"text","la":"Lumen Christi glorióse resurgéntis"},{"k":"text","la":"Díssipet ténebras cordis et mentis."},{"k":"rubric","la":"Mox, celebrans benedicit cereum accensum, dicens:"},{"k":"macro","name":"DominusVobiscum"},{"k":"text","la":"Orémus."},{"k":"text","la":"Véniat, quǽsumus, omnípotens Deus, super hoc incénsum céreum larga tuæ bene + dictiónis infúsio: et hunc noctúrnum splendórem invisíbilis regenerátor, inténde; ut non solum sacrifícium, quod hac nocte litátum est, arcána lúminis tui admixtióne refúlgeat; sed in quocúmque loco ex hujus sanctificatiónis mystério aliquid fúerit deportátum, expúlsa diabólicæ fraudis nequítia, virtus tuæ majestátis assístat. Per Christum Dóminum nostrum."},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"rubric","la":"Interim luminaria ecclesiæ exstinguuntur."},{"k":"sep"},{"k":"head","la":"De solemni processione"},{"k":"rubric","la":"Tum celebrans iterum ponit incensum ! in thuribulo; postea diaconus, depositis ! paramentis violaceis, et indutus stola ! et dalmatica albi coloris, accipit cereum ! paschalem accensum, et ordinatur processio: ! præcedit thuriferarius, sequitur subdiaconus ! cum cruce, diaconus cum cereo accenso, ! post eum statim celebrans, deinde ! clerus per ordinem, et populus."},{"k":"sep"},{"k":"rubric","la":"(Tum sacerdos, depositis paramentis ! violaceis, et indutus stola et dalmatica albi ! coloris, iterum ponit incensum in thuribulo; ! postea accipit cereum paschalem accensum, ! et ordinatur processio: precedit thuriferarius, ! sequitur crucifer, post eum statim sacerdos ! cum cereo accenso, deinde ceteri ministrantes, ! et populus.)"},{"k":"sep"},{"k":"rubric","la":"Cum diaconus ingressus est ecclesiam, ! stans, cantat solus:"},{"k":"text","la":"Lumen Christi.","mark":"V"},{"k":"rubric","la":"cui omnes alii, prater subdiaconum et thuriferarium, ! genuflectentes versus cereum benedictum, ! respondent:"},{"k":"text","la":"Deo grátias.","mark":"R"},{"k":"rubric","la":"Celebrans vero de cereo benedicto propriam ! candelam accendit."},{"k":"sep"},{"k":"rubric","la":"Procedens ad medium ecclesiæ, ibi eodem ! modo diaconus altius cantat"},{"k":"text","la":"Lumen Christi.","mark":"V"},{"k":"rubric","la":"cui omnes, ut supra, genuflectentes, ! respondent:"},{"k":"text","la":"Deo grátias.","mark":"R"},{"k":"rubric","la":"Et de cereo benedicto accenduntur candelæ cleri."},{"k":"sep"},{"k":"rubric","la":"Tertio procedens ante altare, in medio ! chori, rursum adhuc altius cantat:"},{"k":"text","la":"Lumen Christi.","mark":"V"},{"k":"rubric","la":"cui tertio omnes, ut supra, genuflectentes, respondent:"},{"k":"text","la":"Deo grátias.","mark":"R"},{"k":"rubric","la":"Et accenduntur candelæ: populi de cereo benedicto, et luminaria ecclesiæ."},{"k":"sep"},{"k":"rubric","la":"(Cum sacerdos ingressus est ecclesiam, ! stans, cantat solus: Lumen Christi, cui omnes ! alii, prater cruciferum et thuriferarium, genuflectentes ! versus cereum benedictum, respondent: ! Deo grátias. Tunc unus ex ministrantibus ! de cereo benedicto candelam pro ! sacerdote accendit."},{"k":"rubric","la":"Procedens ad medium ecclesiæ, ibi eodem ! modo sacerdos altius cantat: Lumen Christi, ! cui omnes, ut supra, genuflectentes, respondent: ! Deo grátias. Et de cereo benedicto ! accenduntur candelæ ministrantium."},{"k":"rubric","la":"Tertio procedens ante altare, in medio ! chori, rursum adhuc altius cantat: Lumen ! Christi, cui tertio omnes, ut supra genuflectentes, ! respondent: Deo grátias. Et accenduntur ! candelæ populi de cereo benedicto, et ! luminaria ecclesiæ.)"},{"k":"sep"},{"k":"head","la":"De præconio paschali"},{"k":"rubric","la":"Tunc celebrans vadit ad locum suum ! in choro, in latere Epistolæ; subdiaconus ! cum cruce stat in latere Evangelii, contra ! legile; clerus locum suum occupat in ! scamnis."},{"k":"rubric","la":"Diaconus deponit cereum paschalem in ! medio chori, supra parvum sustentaculum, ! et, postquam celebrans posuerit incensum ! in thuribulo, accipiens librum, petit benedictionem, ! dicens:"},{"k":"text","la":"Iube, domne, benedícere."},{"k":"rubric","la":"Et celebrans subiungit:"},{"k":"text","la":"Dóminus sit in corde tuo, et in lábiis tuis, ut digne et competénter annúntiem suum paschále præcónium: in nómine Patris, et Fílii, + et Spíritus Sancti."},{"k":"rubric","la":"Et diaconus respondet:"},{"k":"text","la":"Amen."},{"k":"text","la":"_`"},{"k":"rubric","la":"(Sacerdos deponit cereum paschalem ! in medio chori, supra parvum sustentaculum, ! seque recipit ad abacum; crucifer stat in latere ! Evangelii, contra legile; ceteri ministrantes ! disponuntur hinc et inde."},{"k":"rubric","la":"Sacerdos vero, postquam posuerit incensum ! in thuribulo, accepto libro, dicit: ! Iube, Dómine, benedícere. - Dóminus ! sit in corde meo, et in lábiis meis: ut digne ! et competénter annúntiem suum paschále ! præcónium. Amen.)"},{"k":"sep"},{"k":"rubric","la":"Postea diaconus vadit ad legile, strato ! albo coopertum, et ponit super eo librum, ! et incensat; deinde, circumiens cereum paschalem, ! etiam illum thurificat."},{"k":"rubric","la":"Tunc surgentibus omnibus, et stantibus, ! ut fit ad Evangelium, diaconus cantat præconium ! paschale, habens ante se cereum ! paschalem, a dextris altare, a sinistris aulam ! ecclesiæ. Dum canitur præconium paschale, ! convenit, ut clerus et populus candelas ! accensas gestent."},{"k":"sep"},{"k":"rubric","la":"(Postea sacerdos vadit ad legile, strato ! albo coopertum, et ponit super eo librum, et ! incensat; deinde, circumiens cereum paschalem, ! etiam illum thurificat."},{"k":"rubric","la":"Tunc surgentibus omnibus, et stantibus, ut ! fit ad Evangelium, ipse sacerdos cantat vel ! legit præconium paschale, habens ante se cereum ! paschalem, a dextris altare, a sinistris ! aulam ecclesiæ. Dum canitur præconium paschale, ! convenit, ut clerus et populus candelas ! accensas gestent.)"},{"k":"sep"},{"k":"text","la":"Exsúltet iam Angélica turba coelórum: exsúltent divína mystéria: et pro tanti Regis victória tuba ínsonet salutáris. Gáudeat et tellus tantis irradiáta fulgóribus: et ætérni Regis splendóre illustráta, totíus orbis se séntiat amisísse calíginem. Lætétur et mater Ecclésia, tanti lúminis adornáta fulgóribus: et magnis populórum vócibus hæc aula resúltet. Quaprópter astántes vos, fratres caríssimi, ad tam miram huius sancti lúminis claritátem, una mecum, quæso, Dei omnipoténtis misericórdiam invocáte. Ut, qui me non meis méritis intra Levitárum númerum dignatus est aggregáre: lúminis sui claritátem infúndens, Cérei huius laudem implére perfíciat. Per Dominum nostrum Jesum Christum, Fílium suum: qui cum eo vivit et regnat in unitáte Spíritus Sancti Deus: Per omnia sǽcula sæculórum."},{"k":"text","la":"Amen.","mark":"R"},{"k":"text","la":"Dóminus vobíscum.","mark":"V"},{"k":"text","la":"Et cum Spíritu tuo.","mark":"R"},{"k":"text","la":"Sursum corda.","mark":"V"},{"k":"text","la":"Habémus ad Dóminum.","mark":"R"},{"k":"text","la":"Grátias agámus Dómino Deo nostro.","mark":"V"},{"k":"text","la":"Dignum et iustum est.","mark":"R"},{"k":"text","la":"Vere dignum et iustum est, invísibilem Deum Patrem omnipoténtem Filiúmque eius unigénitum, Dominum nostrum Iesum Christum, toto cordis ac mentis afféctu et vocis ministério personáre. Qui pro nobis ætérno Patri Adæ débitum solvit: et véteris piáculi cautiónem pio cruóre detérsit. Hæc sunt enim festa paschália, in quibus verus ille Agnus occíditur, cuius sánguine postes fidelium consecrántur. Hæc nox est, in qua primum patres nostros, fílios Israël edúctos de Ægýpto, Mare Rubrum sicco vestígio transíre fecísti. Hæc ígitur nox est, quæ peccatórum ténebras colúmnæ illuminatióne purgávit. Hæc nox est, quæ hódie per univérsum mundum in Christo credéntes, a vítiis sǽculi et calígine peccatórum segregátos, reddit grátiæ, sóciat sanctitáti. Hæc nox est, in qua, destrúctis vínculis mortis, Christus ab ínferis victor ascéndit. Nihil enim nobis nasci prófuit, nisi rédimi profuísset. O mira circa nos tuæ pietátis dignátio! O inæstimábilis diléctio caritátis: ut servum redimeres, Fílium tradidísti! O certe necessárium Adæ peccátum, quod Christi morte delétum est! O felix culpa, quæ talem ac tantum méruit habére Redemptórem! O vere beáta nox, quæ sola méruit scire tempus et horam, in qua Christus ab ínferis resurréxit! Hæc nox est, de qua scriptum est: Et nox sicut dies illuminábitur: Et nox illuminátio mea in deliciis meis. Huius ígitur sanctificátio noctis fugat scélera, culpas lavat: et reddit innocéntiam lapsis et mæstis lætítiam. Fugat ódia, concórdiam parat et curvat impéria."},{"k":"sep"},{"k":"text","la":"In huius ígitur noctis grátia, súscipe, sancte Pater, incénsi huius sacrifícium vespertínum: quod tibi in hac Cérei oblatióne solémni, per ministrórum manus de opéribus apum, sacrosáncta reddit Ecclésia. Sed iam colúmnæ huius præcónia nóvimus, quam in honórem Dei rútilans ignis accéndit. Qui licet sit divísus in partes, mutuáti tamen lúminis detriménta non novit. Alitur enim liquántibus ceris, quas in substántiam pretiósæ huius lámpadis apis mater edúxit. O vere beáta nox, quæ exspoliávit Ægýptios, ditávit Hebrǽos! Nox, in qua terrénis cæléstia, humánis divína iungúntur."},{"k":"sep"},{"k":"text","la":"Orámus ergo te, Dómine: ut Céreus iste in honórem tui nóminis consecrátus, ad noctis huius calíginem destruéndam, indefíciens persevéret. Et in odórem suavitátis accéptus, supérnis lumináribus misceátur. Flammas eius lúcifer matutínus invéniat. Ille, inquam, lúcifer, qui nescit occásum. Ille, qui regréssus ab ínferis, humáno géneri serénus illúxit. Precámur ergo te, Dómine: ut nos fámulos tuos, omnémque clerum, et devotíssimum pópulum: una cum beatíssimo Papa nostro N., et Antístite nostro N., quiéte témporum concéssa, in his paschálibus gáudiis, assídua protectióne régere, gubernáre et conserváre digneris. Réspice étiam ad eos, qui nos in potestáte regunt, et, ineffábili pietátis et misericórdiæ tuæ múnere, dírige cogitatiónes eórum ad iustítiam et pacem, ut de terréna operositáte ad cæléstem pátriam pervéniant cum omni populo tuo. Per eúndem Dóminum nostrum Iesum Christum, Fílium tuum: Qui tecum vivit et regnat in unitáte Spíritus Sancti Deus: per ómnia sǽcula sæculórum."},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"head","la":"De lectionibus"},{"k":"rubric","la":"Post præconium paschale, diaconus, ! depositis paramentis albis, assumit violacea, ! et vadit ad celebrantem."},{"k":"sep"},{"k":"rubric","la":"(Post præconium paschale, sacerdos ! deponit dalmaticam et stolam albi coloris, ! et, indutus iterum stola et pluviali violaceis, ! redit ad legile.)"},{"k":"sep"},{"k":"rubric","la":"Postea leguntur lectiones, sine titulo, ! nec in earum fine respondetur Deo gratias. ! Leguntur vero a lectore, in medio chori, ! ante cereum benedictum, ita quidem ut ! lector habeat a dextris altare, a sinistris ! aulam ecclesiæ. Celebrans et ministri, clerus ! et populus, sedentes auscultant."},{"k":"sep"},{"k":"rubric","la":"(Postea leguntur lectiones, sine titulo, ! nec in earum fine respondetur Deo gratias. ! Leguntur vero a sacerdote, in medio chori, ! ante cereum benedictum, ita quidem ut sacerdos ! habeat a dextris altare, a sinistris ! aulam ecclesiæ. Ministrantes et populus sedentes ! auscultant."},{"k":"rubric","la":"Si vero adsit clericus lector, omnia peraguntur, ! ut supra.)"},{"k":"sep"},{"k":"rubric","la":"In fine lectionis, vel post canticum, ! dicuntur orationes hoc modo: omnes surgunt; ! celebrans dicit Orémus, diaconus ! Flectámus genua, et omnes, una cum ipso ! celebrante, flexis genibus, per aliquod temporis ! spatium in silentio orant; dicto a diacono ! Leváte, omnes surgunt, et celebrans ! dicit orationem, in tono feriali, et iunctis ! manibus."},{"k":"sep"},{"k":"rubric","la":"(In fine lectionis, vel post canticum, ! dicuntur orationes hoc modo: omnes surgunt; ! sacerdos, stans ante legile, dicit: Orémus. ! Flectámus genua, et omnes, una cum ipso sacerdote, ! flexis genibus, per aliquod temporis ! spatium in silentio orant; dicto a sacerdote ! Leváte, omnes surgunt, et ipse dicit orationem, ! in tono feriali, et iunctis manibus.)"},{"k":"sep"},{"k":"rubric","la":"Leguntur vero quatuor sequentes lectiones, ! cum suis canticis, et orationibus."},{"k":"sep"},{"k":"rubric","la":"Lectio prima"},{"k":"ref","la":"Gen. 1:1-31; 2:1-2"},{"k":"text","la":"In princípio creávit Deus cælum et terram. Terra áutem erat inánis et vácua, et ténebræ erant super fáciem abýssi: et Spíritus Dei ferebátur super aquas. Dixítque Deus: Fiat lux. Et facta est lux. Et vidit Deus lucem quod esset bona: et divísit lucem a ténebris. Appellavítque lucem Diem, et ténebras Noctem: factúmque est véspere et mane, dies unus. Dixit quoque Deus: Fiat firmaméntum in médio aquárum: et dívidat aquas ab aquis. Et fecit Deus firmaméntum, divisítque aquas quæ erant sub firmaménto, ab his quæ erant super firmaméntum. Et factum est ita. Vocávit Deus firmaméntum Cælum: et factum est véspere et mane, dies secúndus. Dixit vero Deus: Congregéntur aquæ, quæ sub cælo sunt, in locum unum: et appáreat árida. Et factum est ita. Et vocávit Deus aridam, Terram, congregationísque aquárum appellávit Mária. Et vidit Deus quod esset bonum. Et ait: Gérminet terra herbam viréntem, et faciéntem semen, et lignum pomíferum fáciens fructum iuxta genus suum, cuius semen in semetípso sit super terram. Et factum est ita. Et prótulit terra herbam viréntem, et faciéntem semen iuxta genus suum, lignúmque fáciens fructum, et habens unumquódque seméntem secúndum spéciem suam. Et vidit Deus quod esset bonum. Et factum est véspere et mane, dies tértius. Dixit áutem Deus: Fiant luminária in firmaménto cæli, et dívidant diem ac noctem, et sint in signa et témpora, et dies et annos: ut lúminent terram. Et factum est ita. Fecítque Deus duo luminária magna: luminária maius, ut præésset diéi, et lumináre minus, ut præésset nocti: et stellas. Et pósuit eas in firmaménto cæli, ut lucérent super terram, et præéssent diéi ac nocti, et divíderent lucem ac ténebras. Et vidit Deus quod esset bonum. Et factum est véspere et mane, dies quartus. Dixit étiam Deus: Prodúcant aquæ réptile ánimæ vivéntis, et volátile super terram sub firmaménto cæli. Creavítque Deus cete grándia, et omnem ánimam vivéntem atque motábilem, quam prodúxerant aquæ in spécies suas, et omne volátile secúndum genus suum. Et vidit Deus quod esset bonum. Benedixítque eis, dicens: Créscite, et multiplicámini, et repléte aquas maris: avésque multiplicéntur super terram. Et factum est véspere et mane, dies quintus. Dixit quoque Deus: Prodúcat terra ánimam vivéntem in génere suo: iuménta, et reptília, et béstias terræ secúndum spécies suas. Factúmque est ita. Et fecit Deus quod esset bonum, et ait: Faciámus hóminem ad imáginem et similitúdinem nostram: et præsit píscibus maris, et volatílibus cæli, et béstiis, universáeque terræ, omníque réptili quod movétur in terra. Et creávit Deus hóminem ad imáginem suam: ad imáginem Dei creávit illum, másculum et féminam creávit eos. Benedixítque illis Deus, et ait: Créscite et multiplicámini, et repléte terram, et subjícite eam, et dominámini píscibus maris, et volatílibus cæli, et univérsis animántibus, quæ movéntur super terram. Dixítque Deus: Ecce dedi vobis omnem herbam afferéntem semen super terram, et univérsa ligna quæ habent in semetípsis seméntum géneris sui, ut sint vobis in escam: et cunctis animántibus terræ, omníque vólucri cæli, et univérsis, quæ movéntur in terra, et in quibus est ánima vivens, ut hábeant ad vescéndum. Et factum est ita. Vidítque Deus cuncta quæ fécerat: et erant valde bona. Et factum est véspere et mane, dies sextus. Igitur perfécti sunt cæli et terra, et omnis ornátus eórum. Complevítque Deus die séptimo opus suum quod fécerat: et requiévit die séptimo ab univérso ópere quod patrárat."},{"k":"text","la":"_`"},{"k":"text","la":"Orémus."},{"k":"text","la":"Flectámus génua.","mark":"V"},{"k":"text","la":"Leváte.","mark":"R"},{"k":"text","la":"Deus, qui mirabíliter creásti hóminem, et mirabílius redemísti: da nobis, quǽsumus, contra oblectaménta peccáti, mentis ratióne persístere; ut mereámur ad ætérna gáudia perveníre."},{"k":"macro","name":"Per Dominum"},{"k":"sep"},{"k":"rubric","la":"Lectio secunda"},{"k":"ref","la":"Exod 14:24-31; 15:1"},{"k":"text","la":"In diébus illis: Factum est in vigília matutína, et ecce respíciens Dóminus super castra Ægyptiórum per colúmnam ignis et nubis, interfécit exércitum eórum: et subvértit rotas cúrruum, ferebantúrque in profúndum. Dixérunt ergo Ægýptii: Fugiámus Israëlem: Dóminus enim pugnat pro eis contra nos. Et ait Dóminus ad Móysen: Exténde manum tuam super mare, ut revertántur aquæ ad Ægýptios super currus et équites eórum. Cumque extendísset Móyses manum contra mare, revérsum est primo dilúculo ad priórem locum: fugientibúsque Ægýptiis occurrérunt aquæ, et invólvit eos Dóminus in médiis flúctibus. Reversáeque sunt aquæ, et operuérunt currus et équites cuncti exércitus Pharaónis, qui sequéntes ingréssi fúerant mare: nec unus quidem supérfuit ex eis. Fílii áutem Israël perrexérunt per médium sicci maris, et aquæ eis erant quasi pro muro a dextris et a sinístris: liberavítque Dóminus in die illa Israël de manu Ægyptiórum. Et vidérunt Ægýptios mórtuos super littus maris, et manum magnam. quam exercúerat Dóminus contra eos: timuítque pópulus Dóminum, et credidérunt Dómino, et Móysi servo eius. Tunc cécinit Móyses, et fílii Israël carmen hoc Dómino, et dixérunt:"},{"k":"text","la":"_`"},{"k":"rubric","la":"Canticum"},{"k":"ref","la":"Exod 15:1-2"},{"k":"text","la":"Cantémus Dómino: glorióse enim honorificátus est: equum et ascensórum proiécit in mare: adiútor, et protéctor factus est mihi in salútem."},{"k":"text","la":"Hic Deus meus, et honorificábo eum: Deus patris mei, et exaltábo eum.","mark":"V"},{"k":"text","la":"Dóminus cónterens bella: Dóminus nomen est illi.","mark":"V"},{"k":"text","la":"_`"},{"k":"text","la":"Orémus."},{"k":"text","la":"Flectámus génua.","mark":"V"},{"k":"text","la":"Leváte.","mark":"R"},{"k":"text","la":"Deus, cuius antíqua mirácula étiam nostris sǽculis coruscáre sentímus: dum quod uni pópulo, a persecutióne Ægyptíaca liberándo, déxteræ tuæ poténtia contulísti, id in salútem géntium per aquam regeneratiónis operáris: præsta; ut in Abrahæ fílios, et in Israelíticam dignitátem, totíus mundi tránseat plenitúdo."},{"k":"macro","name":"Per Dominum"},{"k":"sep"},{"k":"rubric","la":"Lectio tertia"},{"k":"ref","la":"Isa 4:2-6"},{"k":"text","la":"In die illa erit germen Dómini in magnificéntia, et glória, et fructus terræ sublímis, et exultátio his, qui salváti fúerint de Israël. Et erit: Omnis qui relíctus fúerit in Sion, et resíduus in Ierúsalem, sanctus vocábitur, omnis qui scriptus est in vita in Ierúsalem. Si ablúerit Dóminus sordes filiárum Sion, et sánguinem Ierúsalem láverit de médio eius, in spíritu iudícii, et spíritu ardóris. Et creábit Dóminus super omnem locum montis Sion, et ubi invocátus est, nubem per diem, et fumum, et splendórem ignis flammántis in nocte: super omnem enim glóriam protéctio. Et tabernáculum erit in umbráculum diéi ab æstu, et in securitátem, et absconsiónem a túrbine, et a plúvia."},{"k":"text","la":"_`"},{"k":"rubric","la":"Canticum"},{"k":"ref","la":"Isa 5:1-2"},{"k":"text","la":"Vínea facta est dilécto in cornu, in loco úberi."},{"k":"text","la":"Et macériam circúmdedit, et circumfodit: et plantávit víneam Sorec: et ædificávit turrim in médio eius.","mark":"V"},{"k":"text","la":"Et tórcular fodit in ea: vínea enim Dómini Sábaoth, domus Israël est.","mark":"V"},{"k":"text","la":"_`"},{"k":"text","la":"Orémus."},{"k":"text","la":"Flectámus génua.","mark":"V"},{"k":"text","la":"Leváte.","mark":"R"},{"k":"text","la":"Deus, qui in ómnibus Ecclésiæ tuæ fíliis sanctórum prophetárum voce manifestásti, in omni loco dominatiónis tuæ, satórem te bonórum séminum, et electórum pálmitum esse cultórem: tríbue pópulis tuis, qui et vineárum apud te nómine censéntur, et ségetum; ut, spinárum et tribulórum squalóre resecáto, digna efficiántur fruge fecúndi."},{"k":"macro","name":"Per Dominum"},{"k":"sep"},{"k":"rubric","la":"Lectio quarta"},{"k":"ref","la":"Deut 31:22-30"},{"k":"text","la":"In diébus illis: Scripsit ergo Móyses cánticum et dócuit fílios Israël. Præcepítque Dóminus Iósue fílio Nun et ait: Confortáre, et esto robústus: tu enim introdúces fílios Israël in terram, quam pollícitus sum, et ego ero tecum. Postquam ergo scripsit Moses verba legis huius in volúmine, atque conplévit: præcépit Levítis, qui portábant arcam fœ́deris Dómini dicens: Tóllite librum istum, et pónite eum in látere arcæ fœ́deris Dómini Dei vestri: ut sit ibi contra te in testimónium. Ego enim scio contentiónem tuam, et cervícem tuam duríssimam. Adhuc vivénte me, et ingrediénte vobíscum, semper contentióse egístis contra Dóminum: quanto magis cum mórtuus fúero? Congregáte ad me omnes maióres natu per tribus vestras, atque doctóres, et loquar audiéntibus eis sermónes istos, et invocábo contra eos cælum et terram. Novi enim quod post mortem meam iníque agétis, et declinábitis cito de via, quam præcépi vobis: et occúrrent vobis mala in extrémo témpore, quando fecéritis malum in conspéctu Dómini, ut irritétis eum per ópera mánuum vestrárum. Locútus est ergo Móyses, audiénte univérso cœtu Israël, verba cárminis huius, et ad finem usque conplévit:"},{"k":"text","la":"_`"},{"k":"rubric","la":"Canticum"},{"k":"ref","la":"Deut. 32:1-4"},{"k":"text","la":"Atténde, cælum, et loquar: et áudiat terra verba ex ore meo."},{"k":"text","la":"Exspectétur sicut plúvia elóquium meum: et descéndant sicut ros verba mea, sicut imber super grámina.","mark":"V"},{"k":"text","la":"Et sicut nix super fænum: quia nomen Dómini invocábo.","mark":"V"},{"k":"text","la":"Date magnitúdinem Deo nostro: Deus, vera ópera eius, et omnes viæ eius iudícia.","mark":"V"},{"k":"text","la":"Deus fidélis, in quo non est iníquitas: iustus et sanctus Dóminus.","mark":"V"},{"k":"text","la":"_`"},{"k":"text","la":"Orémus."},{"k":"text","la":"Flectámus génua.","mark":"V"},{"k":"text","la":"Leváte.","mark":"R"},{"k":"text","la":"Deus, celsitúdo humílium et fortitúdo rectórum, qui per sanctum Móysen púerum tuum, ita erudíre pópulum tuum sacri cárminis tui decantatióne voluísti, ut illa legis iterátio fíeret étiam nostra diréctio: excíta in omnem iustificatárum géntium plenitúdinem poténtiam tuam, et da lætítiam, mitigándo terrórem; ut, ómnium peccátis tua remissióne delétis, quod denuntiátum est in ultiónem, tránseat in salútem."},{"k":"macro","name":"Per Dominum"},{"k":"sep"},{"k":"head","la":"De prima parte Litaniarum"},{"k":"rubric","la":"His expletis, a duobus cantoribus, in medio chori genuflexis, cantantur ! Litaniæ Sanctorum (quin tamen duplicentur) usque ad invocationem ! Propitius esto, omnibus genuflexis et respondentibus."},{"k":"sep"},{"k":"rubric","la":"(His expletis, a duobus cantoribus, seu, his deficientibus, ab ipso ! sacerdote, genuflexo in infimo gradu altaris, a latere Epistolæ, ! cantantur Litaniæ Sanctorum (quin tamen duplicentur) usque ad ! invocationem Propitius esto, omnibus genuflexis et respondentibus.)"},{"k":"text","la":"Kýrie eléison.","mark":"V"},{"k":"text","la":"Kýrie eléison.","mark":"R"},{"k":"text","la":"Christe eléison.","mark":"V"},{"k":"text","la":"Christe eléison.","mark":"R"},{"k":"text","la":"Kýrie eléison.","mark":"V"},{"k":"text","la":"Kýrie eléison.","mark":"R"},{"k":"text","la":"Pater de cǽlis, Deus. R. Miserére nobis.","mark":"V"},{"k":"text","la":"Fili Redémptor mundi, Deus. R. Miserére nobis.","mark":"V"},{"k":"text","la":"Spíritus Sancte, Deus. R. Miserére nobis.","mark":"V"},{"k":"text","la":"Sancta Trínitas, unus Deus. R. Miserére nobis.","mark":"V"},{"k":"text","la":"Sancta María. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Sancta Dei Génetrix. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Sancta Virgo vírginum. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Sancte Míchaël. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Sancte Gábriel. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Sancte Ráphaël. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Omnes sancti Angeli et Archángeli. R. Oráte pro nobis.","mark":"V"},{"k":"text","la":"Omnes sancti beatórum Spirítuum órdines. R. Oráte pro nobis.","mark":"V"},{"k":"sep"},{"k":"text","la":"Sancte Ioánnes Baptísta. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Sancte Ioseph. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Omnes sancte Patriárchæ et Prophétæ. R. Oráte pro nobis.","mark":"V"},{"k":"sep"},{"k":"text","la":"Sancte Petre. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Sancte Paule. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Sancte Andréa. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Sancte Ioánnes. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Omnes sancti Apóstoli et Evangelístæ. R. Oráte pro nobis.","mark":"V"},{"k":"text","la":"Omnes sancti Discípuli Dómini. R. Oráte pro nobis.","mark":"V"},{"k":"sep"},{"k":"text","la":"Sancte Stéphane. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Sancte Laurénti. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Sancte Vincénti. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Omnes sancti Mártyres. R. Oráte pro nobis.","mark":"V"},{"k":"text","la":"Sancte Silvéster. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Sancte Gregóri. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Sancte Augustíne. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Omnes sancti Pontífices et Confessóres. R. Oráte pro nobis.","mark":"V"},{"k":"text","la":"Omnes sancti Doctóres. R. Oráte pro nobis.","mark":"V"},{"k":"sep"},{"k":"text","la":"Sancte Antóni. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Sancte Benedícte. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Sancte Domínice. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Sancte Francísce. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Omnes sancti Sacerdótes et Levítæ. R. Oráte pro nobis.","mark":"V"},{"k":"text","la":"Omnes sancti Mónachi et Eremítæ. R. Oráte pro nobis.","mark":"V"},{"k":"sep"},{"k":"text","la":"Sancta María Magdaléna. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Sancta Agnes. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Sancta Cæcília. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Sancta Agatha. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Sancta Anastásia. R. Ora pro nobis.","mark":"V"},{"k":"text","la":"Omnes sanctæ Vírgines et Víduæ. R. Oráte pro nobis.","mark":"V"},{"k":"text","la":"Omnes Sancti et Sanctæ Dei. R. Intercédite pro nobis.","mark":"V"},{"k":"rubric","la":"Postea, si ecclesia habet fontem baptismalem, ritus prosequitur ut ! infra."},{"k":"sep"},{"k":"head","la":"De benedictione aquæ baptismalis"},{"k":"rubric","la":"Dum cantantur Litaniæ Sanctorum, vas aquæ baptismalis benedicendæ, et ! cetera omnia quæ ad benedictionem requiruntur, præparantur in medio ! chori, versus latus Epistolæ, in conspectu fidelium. Vas aquæ ! benedicendæ convenienter ornari decet."},{"k":"sep"},{"k":"rubric","la":"In benedicenda aqua baptismali celebrans, stans coram populo, ante ! se habeat vas aquæ baptismalis benedicendæ, a dextris cereum ! benedictum, a sinistris alium subdiaconum, vel clericum, seu ! ministrantem, stantem cum cruce. Celebrans, iunctis manibus, in tono ! feriali dicit:"},{"k":"macro","name":"DominusVobiscum"},{"k":"text","la":"Orémus."},{"k":"text","la":"Omnípotens sempitérne Deus, adésto magnæ pietátis tuæ mystériis, adésto sacraméntis: et ad recreándos novos pópulos, quos tibi fons baptismátis párturit, spíritum adoptiónis emítte ; ut, quod nostræ humilitátis geréndum est ministério, virtútis tuæ impleátur efféctu. Per Dóminum nostrum Iesum Christum, Fílium tuum: Qui tecum vivit et regnat in unitáte Spíritus Sancti Deus:"},{"k":"rubric","la":"Elevans vocem in modum præfationis, prosequitur iunctis manibus:"},{"k":"text","la":"Per ómnia sǽcula sæculórum."},{"k":"text","la":"Amen.","mark":"R"},{"k":"text","la":"Dóminus vobíscum.","mark":"V"},{"k":"text","la":"Et cum spíritu tuo.","mark":"R"},{"k":"text","la":"Sursum corda.","mark":"V"},{"k":"text","la":"Habémus ad Dóminum.","mark":"R"},{"k":"text","la":"Grátias agámus Dómino Deo nostro.","mark":"V"},{"k":"text","la":"Dignum et iustum est.","mark":"R"},{"k":"text","la":"Vere dignum et iustum est, æquum et salutare, nos tibi semper et ubique gratias agere, Domine, sancte Pater, omnipotens æterne Deus: qui invisibili potentia, sacramentorum tuorum mirabiliter operaris effectum: et licet nos tantis mysteriis exsequendis simus indigni: tu tamen gratiæ tuæ dona non deserens, etiam ad nostras preces aures tuæ pietatis inclinas. Deus, cuius Spiritus super aquas inter ipsa munda primordia ferebatur: ut iam tunc virtutem sanctificationis, aquarum natura conciperet. Deus, qui nocentis mundi crimina per aquas abluens, regenerationis speciem in ipsa diluvii effusione signasti: ut, unius eiusdemque elementi mysterio, et finis esset vitiis, et origo virtutibus. Respice, Domine, in faciem Ecclesiæ tuæ, et multiplica in ea regenerationes tuas, qui gratiæ tuæ affluentis impetu lætificas civitatem tuam: fontemque baptismatis aperis toto orbe terrarum gentibus innovandis: ut, tuæ maiestatis imperio, sumat Unigeniti tui gratiam de Spiritu Sancto."},{"k":"sep"},{"k":"rubric","la":"Hic celebrans in modum crucis aquam dividit manu extensa, ! quam statim linteo extergit, dicens:"},{"k":"sep"},{"k":"text","la":"Qui hanc aquam, regenerándis homínibus præparátam, arcána sui núminis admixtióne fecúndet: ut, sanctificatióne concépta, ab immaculáto divíni fontis útero, in novam renáta creatúram, progénies cæléstis emérgat: et quos aut sexus in córpore, aut ætas discérnit in témpore, omnes in unam páriat grátia mater infántiam. Procul ergo hinc, iubénte te, Dómine, omnis spíritus immúndus abscédat: procul tota nequítia diabólicæ fráudis absístat. Nihil hoc loci hábeat contráriæ virtútis admíxtio: non insidiándo circúmvolet: non laténdo subrépat: non inficiéndo corrúmpat."},{"k":"sep"},{"k":"rubric","la":"Aquam manu tangit."},{"k":"sep"},{"k":"text","la":"Sit hæc sancta et ínnocens creatúra, líbera ab omni impugnatóris incúrsu, et totíus nequítiæ purgáta discéssu. Sit fons vivus, aqua regénerans, unda puríficans: ut omnes hoc lavácro salutífero diluéndi, operánte in eis Spíritu Sancto, perféctæ purgatiónis indulgéntiam consequántur."},{"k":"sep"},{"k":"rubric","la":"Facit crucem super aquam, dicens:"},{"k":"sep"},{"k":"text","la":"Unde benedíco te, creatúra aquæ, per Deum + vivum, per Deum + verum, per Deum + sanctum: per Deum, qui te, in princípio, verbo separávit ab árida: cuius Spíritus super te ferebátur."},{"k":"sep"},{"k":"rubric","la":"Hic manu aquam dividit, et effundit eam versus quatuor mundi partes, dicens:"},{"k":"sep"},{"k":"text","la":"Qui te paradísi fonte manáre fecit, et in quátuor flumínibus totam terram rigáre præcépit. Qui te in desérto amáram, suavitáte índita, fecit esse potábilem, et sitiénti pópulo de petra prodúxit. Bene + dico te et per Iesum Christum Fílium eius únicum, Dóminum nostrum: qui te in Cana Galilææ signo admirábili, sua poténtia convértit in vinum. Qui pédibus super te ambulávit: et a Ioánne in Iordáne in te baptizátus est. Qui te una cum sánguine de látere suo prodúxit: et discípulis suis iussit, ut credéntes baptizaréntur in te, dicens: Ite, docéte omnes gentes, baptizántes eos in nómine Patris, et Fílii, et Spíritus Sancti."},{"k":"sep"},{"k":"rubric","la":"Mutat vocem, et prosequitur recto tono:"},{"k":"sep"},{"k":"text","la":"Hæc nobis præcépta servántibus tu, Deus omnípotens, clemens adésto: tu benígnus aspíra."},{"k":"sep"},{"k":"rubric","la":"Halat ter in aquam in modum crucis, dicens:"},{"k":"sep"},{"k":"text","la":"Tu has símplices aquas tuo ore benedícito: ut præter naturálem emundatiónem, quam lavándis possunt adhibére corpóribus, sint étiam purificándis méntibus efficáces."},{"k":"sep"},{"k":"rubric","la":"Hic celebrans paululum demittit cereum in aquam: et resumens tonum præfationis, dicit:"},{"k":"sep"},{"k":"text","la":"Descéndat in hanc plenitúdinem fontis virtus Spíritus Sancti."},{"k":"sep"},{"k":"rubric","la":"Deinde extractum cereum de aqua, iterum profundius mergit, aliquanto ! altius repetens:"},{"k":"sep"},{"k":"text","la":"Descéndat in hanc plenitúdinem fontis virtus Spíritus Sancti."},{"k":"sep"},{"k":"rubric","la":"Postea cereum rursus de aqua ! extractum, tertio immergens usque ad fundum, altiori adhuc voce repetit:"},{"k":"sep"},{"k":"text","la":"Descéndat in hanc plenitúdinem fontis virtus Spíritus Sancti."},{"k":"sep"},{"k":"rubric","la":"Descendat, ut supra. Et deinde sufflans ter in aquam, secundum hanc ! figuram &Psi;, prosequitur:"},{"k":"sep"},{"k":"text","la":"Totámque huius aquæ substántiam, regenerándi fecúndet efféctu."},{"k":"text","la":"Totámque huius aquæ substántiam, regenerándi fecúndet efféctu."},{"k":"text","la":"Totámque huius aquæ substántiam, regenerándi fecúndet efféctu."},{"k":"sep"},{"k":"rubric","la":"Hic tollitur cereus de aqua, et prosequitur:"},{"k":"sep"},{"k":"text","la":"Hic ómnium peccatórum máculæ deleántur: hic natúra ad imáginem tuam cóndita, et ad honórem sui reformáta princípii, conctis vetustátis squalóribus emundétur: ut omnis homo, sacraméntum hoc regeneratiónis ingréssus, in veræ innocéntiæ novam infántium renascátur."},{"k":"sep"},{"k":"rubric","la":"Sequentia dicit legendo:"},{"k":"sep"},{"k":"text","la":"Per Dóminum nostrum Iesum Christum Fílium tuum: qui ventúrus est iudicáre vivos et mórtuos, et sǽculum per ignem. R. Amen."},{"k":"sep"},{"k":"rubric","la":"Deinde aliquis clericus, vel ministrans, accipit in vase aliquo de eadem ! aqua, ad aspergendum populum post renovationem promissionum Baptismatis, ! ut infra, dicetur, et ad aspergendum in domibus et aliis locis."},{"k":"sep"},{"k":"rubric","la":"His peractis, celebrans, qui benedicit aquam, infundit de oleo ! catechumenorum in eam in modum crucis, intellegibili voce dicens:"},{"k":"text","la":"Sanctificétur + et fecundétur fons iste Oleo salútis renascéntibus ex eo, in vitam ætérnam."},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"rubric","la":"Deinde infundit de chrismate, modo quo supra, dicens:"},{"k":"text","la":"Infúsio Chrísmatis Dómini nostri Iesu Christi, et Spíritus Sancti Parácliti, fiat in nómine santæ Trinitátis."},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"rubric","la":"Postea accipit ambas ampullas dicti olei sancti, et chrismatis, ! et de utroque simul in modum crucis infundendo, dicit:"},{"k":"text","la":"Commíxtio Chrísmatis sanctificatiónis, et Olei unctiónis, et aquæ baptísmatis, páriter fiat in nómine Pa + tris, et Fí + lii, et Spíritus + Sancti."},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"rubric","la":"Tunc miscet ipsum oleum cum aqua. Si aderunt baptizandi, eos baptizet ! more consueto. Sed, præsertim si plures sint, permittitur cæremonias ! Ritualis romani, quæ ipsam Baptismi collationem præcedunt, id est, in ! Baptismate infantium usque ad verba Credis in Deum (Rituale romanum, ! tit. II, cap. II, n. 17), et in Baptismate adultorum usque ad verba Quis ! vocaris? (Rituale romanum, tit. II, cap. IV, n. 37), eodem mane, tempore ! opportuno, præmittere."},{"k":"sep"},{"k":"rubric","la":"Benedictione peracta, aqua baptismalis defertur processionaliter ad ! fontem, hoc modo: præcedit thuriferarius, sequitur alius subdiaconus, ! vel clericus, cum cruce, et clerus; deinde diaconus cum vase aquæ ! baptismalis, nisi conveniat ipsum ab acolythis portari, et celebrans; ! cereus vero paschalis remanet in suo loco; et interim cantatur sequens"},{"k":"sep"},{"k":"rubric","la":"Canticum"},{"k":"ref","la":"Ps 41:2-4"},{"k":"text","la":"Sicut cervus desíderat ad fontes aquárum: ita desíderat ánima mea ad te, Deus."},{"k":"text","la":"Sitívit ánima mea ad Deum vivum, quando véniam, et apparébo ante fáciem Dei?","mark":"V"},{"k":"text","la":"Fuérunt mihi lácrymæ meæ panes die ac nocte, dum dícitur mihi per síngulos dies: Ubi est Deus tuus?","mark":"V"},{"k":"rubric","la":"Aqua baptismali in fontem immissa, celebrans, manibus iunctis et in tono feriali, dicit:"},{"k":"macro","name":"DominusVobiscum"},{"k":"text","la":"Orémus."},{"k":"text","la":"Omnípotens sempitérne Deus, réspice propítius ad devotiónem pópuli renascéntis, qui sicut cervus, aquárum tuárum éxpetit fontem: et concéde propítius; ut fídei ipsíus sitis, baptísmatis mystério, ánimam corpúsque sanctíficet. Per Dóminum nostrum Iesum Christum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum."},{"k":"text","la":"Amen.","mark":"R"},{"k":"rubric","la":"Et incensat fontem."},{"k":"sep"},{"k":"rubric","la":"Tunc redeunt omnes in silentio in chorum, et datur initium renovationi ! promissionum Baptismatis."},{"k":"sep"},{"k":"rubric","la":"(Benedictione peracta, aqua baptismalis defertur processionaliter ! ad fontem, hoc modo: præcedit thuriferarius, sequuntur crucifer et ! ministrantes; deinde unus vel plures ministrantium, qui vas aquæ ! baptismalis gestant, et sacerdos; cereus vero paschalis remanet in suo ! loco. Cetera fiunt ut supra.)"},{"k":"sep"},{"k":"rubric","la":"Sicubi vero baptisterium exstat ab ecclesia separatum, et ! præferatur benedictionem aquæ baptismalis in ipso baptisterio fieri, ! post invocationem Sancta Trínitas, unus Deus, miserere nobis, ! descenditur ad fontem hoc modo: præcedit clericus cum cereo benedicto, ! sequitur alius subdiaconus cum cruce, vel crucifer, medius inter ! acolythos cum candelabris accensis, deinde clerus per ordinem, demum ! celebrans cum ministris sacris. Cantores vero et populus remanent in ! locis suis, et prosequuntur cantum Litaniarum, repetitis, si opus est, ! invocationibus inde a Sancta María, ora pro nobis. Benedictio aquæ ! baptismalis fit ut supra, his tantum mutatis: dum pergitur ad fontem, ! cantatur canticum Sicut cervus, et celebrans, antequam intret ad ! benedictionem fontis, dicit orationem Omnípotens sempitérne Deus, ! respice propitius; postea procedit ad benedictionem fontis. ! Benedictione peracta, omnes redeunt in silentio in ecclesiam, ! et datur initium renovationi promissionum Baptismatis."},{"k":"sep"},{"k":"head","la":"De renovatione promissionum baptismatis"},{"k":"rubric","la":"Completa benedictione aquæ baptismalis, eiusque translatione ad fontem, ! vel, ubi benedictio locum non habuerit, post absolutam primam partem ! Litaniarum, proceditur ad renovationem promissionum Baptismatis, qua ! perdurante convenit, ut clerus et populus candelas accensas gestent."},{"k":"sep"},{"k":"rubric","la":"Celebrans, depositis paramentis violaceis, assumit stolam et ! pluviale albi coloris; deinde, imposito thure, et facta incensatione ! cerei, stans iuxta illum, facie versus ad populum, vel ex ambone seu ! pulpito, incipit, ut sequitur:"},{"k":"sep"},{"k":"text","la":"Hac sacratíssima nocte, fratres caríssimi, sancta Mater Ecclésia, recólens Dómini nostri Iesu Christi mortem ei sepultúram, eum redamándo vígilat; et, célebrans eiúsdem gloriósam resurrectiónem, lætabúnda gáudet."},{"k":"sep"},{"k":"text","la":"Quóniam vero, ut docet Apóstolus, consepúlti sumus cum Christo per baptísmum in mortem, quómodo Christus resurréxit a mórtuis, ita et nos in novitáte vitæ opórtet ambuláre; sciéntes, véterem hóminem nostrum simul cum Christo crucifíxum esse, ut ultra non serviámus peccáto. Existimémus ergo nos mórtuos quidem esse peccáto, vivéntis áutem Deo in Christo Iesu Dómino nostro."},{"k":"sep"},{"k":"text","la":"Quaprópter, fratres caríssimi, quadragesimáli exercitatióne absolúta, sancti baptísmatis promissiónis renovémus, quibus olim sátanæ et opéribus eius, sicut et mundo, qui inimícus est Dei, abrenuntiávimus, et Deo in sancta Ecclésia cathólica fidéliter servíre promísimus."},{"k":"sep"},{"k":"text","la":"Itaque:"},{"k":"text","la":"Abrenuntiátis Sátanæ?","mark":"S"},{"k":"text","la":"O. Abrenuntiámus."},{"k":"text","la":"Et ómnibus opéribus eius?","mark":"S"},{"k":"text","la":"O. Abrenuntiámus."},{"k":"text","la":"Et ómnibus pompis eius?","mark":"S"},{"k":"text","la":"O. Abrenuntiámus."},{"k":"text","la":"Créditis in Deum, Patrem omnipoténtem, Creatórem cœli et terræ?","mark":"S"},{"k":"text","la":"O. Crédimus."},{"k":"text","la":"Créditis in Iesum Christum, Fílium eius únicum, Dóminum nostrum, natum et passum?","mark":"S"},{"k":"text","la":"O. Crédimus."},{"k":"text","la":"Créditis et in Spíritum Sanctum, sanctam Ecclésiam cathólicam, Sanctórum communiónem, remissiónem peccatórem, carnis resurrectiónem, et vitam ætérnam?","mark":"S"},{"k":"text","la":"O. Crédimus."},{"k":"text","la":"Nunc áutem una simul Deum precémur, sicut Dóminus noster Iesus Christus oráre nos dócuit:","mark":"S"},{"k":"text","la":"O. Pater noster, qui es in cœlis, sanctificétur nomen tuum. Advéniat regnum tuum. Fiat volúntas tua, sicut in cœlo et in terra. Panem nostrum quotidiánum da nobis hódie, et dimítte nobis débita nostra, sicut et nos dimíttimus debitóribus nostris. Et ne nos indúcas in tentatiónem, sed líbera nos a malo."},{"k":"text","la":"Et Deus omnípotens, Pater Dómini nostri Iesu Christi, qui nos regenerávit ex aqua et Spíritu Sancto, quique nobis dedit remissiónem peccatórum, ipse nos custódiat grátia sua in eódem Christo Iesu Dómino nostro in vitam ætérnam.","mark":"S"},{"k":"text","la":"O. Amen."},{"k":"sep"},{"k":"rubric","la":"Et aspergit populum aqua benedicta, extracta, ut supra dictum est, ! in benedictione aquæ baptismalis; vel, ubi benedictio aquæ ! baptismalis locum non habet, aqua benedicta «ordinaria»."},{"k":"sep"},{"k":"rubric","la":"Hæc allocutio et renovatio promissionum Baptismatis fieri potest, ! ubique locorum, lingua vernacula; versione tamen ab Ordinario loci ! approbata."},{"k":"sep"},{"k":"head","la":"De altera parte Litaniarum"},{"k":"sep"},{"k":"rubric","la":"Renovatione promissionum Baptismatis peracta, cantores, seu ipse ! sacerdos, incipiunt alteram partem Litaniarum, inde ab invocatione ! Propitius esto, usque ad finem, omnibus genuflexis et respondentibus. ! Si in hac sacra Vigilia paschali Ordines conferantur, consueta ! ordinandorum prostrati et benedictio peragitur, dum hæc altera pars ! Litaniarum decantatur."},{"k":"sep"},{"k":"rubric","la":"Celebrans vero et ministri, accedentes ad sacristiam, induuntur ! paramentis albi coloris pro Missa solemniter celebranda."},{"k":"sep"},{"k":"rubric","la":"(Sacerdos vero et ministrantes accedunt ad sacristiam, ubi sacerdos ! induitur paramentis albi coloris, ministrantes vero sumunt vestes ! festivas, pro Missa cantata. Vel si, cantoribus deficientibus, ipse ! sacerdos Litanias Sanctorum decantare debeat, his ab solutis, ad ! sacristiam accedat, cum ministrantibus, ad paramenta sumenda pro Missa ! cant at a, ut supra dictum est.)"},{"k":"sep"},{"k":"rubric","la":"Interim cereus paschalis reponitur in candelabro suo, in latere ! Evangelii, et altare paratur pro Missa solemni, luminaribus accensis et ! floribus."},{"k":"sep"},{"k":"text","la":"Propítius esto. R. Parce nobis, Dómine.","mark":"V"},{"k":"text","la":"Propítius esto. R. Exaudi nos, Dómine.","mark":"V"},{"k":"text","la":"Ab omni malo. R. Líbera nos, Dómine.","mark":"V"},{"k":"text","la":"Ab omni peccáto. R. Líbera nos, Dómine.","mark":"V"},{"k":"text","la":"A morte perpétua. R. Líbera nos, Dómine.","mark":"V"},{"k":"text","la":"Per mystérium sanctæ Incarnatiónis tuæ. R. Líbera nos, Dómine.","mark":"V"},{"k":"text","la":"Per advéntum tuum. R. Líbera nos, Dómine.","mark":"V"},{"k":"text","la":"Per nativitátem tuum. R. Líbera nos, Dómine.","mark":"V"},{"k":"text","la":"Per baptísmum et sanctum ieiúnium tuum. R. Líbera nos, Dómine.","mark":"V"},{"k":"text","la":"Per crucem et passiónem tuam. R. Líbera nos, Dómine.","mark":"V"},{"k":"text","la":"Per mortem et sepultúram tuam. R. Líbera nos, Dómine.","mark":"V"},{"k":"text","la":"Per sanctam resurrectiónem tuam. R. Líbera nos, Dómine.","mark":"V"},{"k":"text","la":"Per admirábilem ascensiónem tuam. R. Líbera nos, Dómine.","mark":"V"},{"k":"text","la":"Per advéntum Spíritus Sancti Parácliti. R. Líbera nos, Dómine.","mark":"V"},{"k":"text","la":"In die iudícii. R. Líbera nos, Dómine.","mark":"V"},{"k":"sep"},{"k":"text","la":"Peccatóres. R. Te rogámus, audi nos.","mark":"V"},{"k":"text","la":"Ut nobis parcas. R. Te rogámus, audi nos.","mark":"V"},{"k":"text","la":"Ut Ecclésiam tuam sanctam régere et conserváre dignéris. R. Te rogámus, audi nos.","mark":"V"},{"k":"text","la":"Ut domnum apostólicum et omnes ecclesiásticos órdines in sancta religióne conserváre dignéris. R. Te rogámus, audi nos.","mark":"V"},{"k":"text","la":"Ut inimícos sanctæ Ecclésiæ humiliáre dignéris. R. Te rogámus, audi nos.","mark":"V"},{"k":"text","la":"Ut régibus et princípibus christiánis, pacem et veram concórdiam donáre dignéris. R. Te rogámus, audi nos.","mark":"V"},{"k":"text","la":"Ut nosmetípsos in tuo sancto servítio confortáre et conserváre dignéris. R. Te rogámus, audi nos.","mark":"V"},{"k":"text","la":"Ut ómnibus benefactóribus nostris sempitérna bona retríbuas. R. Te rogámus, audi nos","mark":"V"},{"k":"text","la":"Ut fructus terræ dare et conserváre dignéris. R. Te rogámus, audi nos.","mark":"V"},{"k":"text","la":"Ut ómnibus fidélibus defúnctis réquiem ætérnam donáre dignéris. R. Te rogámus, audi nos.","mark":"V"},{"k":"text","la":"Ut nos exaudíre dignéris. R. Te rogámus, audi nos.","mark":"V"},{"k":"sep"},{"k":"text","la":"Agnus Dei, qui tollis peccáta mundi. R. Parce nobis, Dómine.","mark":"V"},{"k":"text","la":"Agnus Dei, qui tollis peccáta mundi. R. Exaudi nos, Dómine.","mark":"V"},{"k":"text","la":"Agnus Dei, qui tollis peccáta mundi. R. Miserére nobis.","mark":"V"},{"k":"text","la":"Christe, audi nos.","mark":"V"},{"k":"text","la":"Christe, exáudi nos.","mark":"R"},{"k":"sep"},{"k":"head","la":"De Missa solemni Vigiliæ paschalis"},{"k":"rubric","la":"Celebratio solius Missæ Vigiliæ paschalis sine cæremoniis ! præcedentibus interdicitur."},{"k":"sep"},{"k":"rubric","la":"Sacra Communio fidelibus dari potest tantummodo inter Missarum solemnia, ! vel continuo ac statim ab iis expletis; exceptis iis, qui in periculo ! mortis sunt constituti."},{"k":"sep"},{"k":"rubric","la":"In fine Litaniarum, cantores solemniter incipiunt Kyrie, eléison, ut in ! Missa moris est. Interim celebrans cum ministris, in paramentis albis, ! seu cum ministrantibus, accedit ad altare, et, facta ei debita ! reverentia, omissis psalmo Iudica me, Deus, et confessione, statim ! ascendens, osculatur illud in medio, et incensat more solito."},{"k":"sep"},{"k":"rubric","la":"Celebrans benedicit, dicens:"},{"k":"text","la":"Ab illo bene + dicáris, in cujus honore cremáberis. Amen."},{"k":"sep"},{"k":"head","la":"Kyrie"},{"k":"text","la":"Kýrie, eléison.","mark":"S"},{"k":"text","la":"Kýrie, eléison.","mark":"M"},{"k":"text","la":"Kýrie, eléison.","mark":"S"},{"k":"text","la":"Christe, eléison.","mark":"M"},{"k":"text","la":"Christe, eléison.","mark":"S"},{"k":"text","la":"Christe, eléison.","mark":"M"},{"k":"text","la":"Kýrie, eléison.","mark":"S"},{"k":"text","la":"Kýrie, eléison.","mark":"M"},{"k":"text","la":"Kýrie, eléison.","mark":"S"}]},"hr":{}});
